    if not kept_rows:
        return []

    kept_length = len(kept_rows)
    rotation_amount = final_state % kept_length
    rotated_rows = kept_rows[rotation_amount:] + kept_rows[:rotation_amount]

    integer_times = []
    for row in rotated_rows:
        if isinstance(row, int):
            integer_times.append(row)

    integer_times.sort()
    deduplicated_times = []
    for time in integer_times:
        if not deduplicated_times or time != deduplicated_times[-1]:
            deduplicated_times.append(time)

    sessions = []
    if deduplicated_times:
        start = deduplicated_times[0]
        end = deduplicated_times[0]
        count = 1
        for i in range(1, len(deduplicated_times)):
            if deduplicated_times[i] - end > 3:
                sessions.append([start, end, count])
                start = deduplicated_times[i]
                end = deduplicated_times[i]
                count = 1
            else:
                end = deduplicated_times[i]
                count += 1
        sessions.append([start, end, count])

    return sessions

